// ABOUTME: Pins the Helmert datum shift of every table CRS against PROJ reference positions.
// ABOUTME: Reads tests/fixtures/datum-shift-reference.txt, generated by tools/gen_datum_shifts.py.
//! Reference parity for source CRSs that need a datum shift to WGS 84.
//!
//! The fixture holds, for every CRS in the datum shift table, source
//! coordinates inside the EPSG area of use and the EPSG:4978 position that
//! PROJ computes for them with the same EPSG coordinate operation. The
//! reprojector must agree with PROJ on every row.

use std::path::Path;

use tileforge_crs::{Reprojector, SourceCrs};

/// Largest accepted distance between the reprojector and PROJ, in metres.
/// The two share the Helmert parameters, so the difference is numerical only:
/// the worst row measured 2.5 µm when the fixture was generated.
const PARITY_TOLERANCE_M: f64 = 1.0e-5;

struct Row {
    epsg: u16,
    src: [f64; 3],
    expected_ecef: [f64; 3],
}

fn reference_rows() -> Vec<Row> {
    let path =
        Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/datum-shift-reference.txt");
    let body =
        std::fs::read_to_string(&path).unwrap_or_else(|e| panic!("read {}: {e}", path.display()));
    body.lines()
        .map(str::trim)
        .filter(|line| !line.is_empty() && !line.starts_with('#'))
        .map(|line| {
            let cols: Vec<&str> = line.split_whitespace().collect();
            assert_eq!(cols.len(), 7, "expected 7 fields in {line:?}");
            let number = |i: usize| {
                cols[i]
                    .parse::<f64>()
                    .unwrap_or_else(|e| panic!("{:?} is not f64: {e}", cols[i]))
            };
            Row {
                epsg: cols[0].parse().expect("EPSG code"),
                src: [number(1), number(2), number(3)],
                expected_ecef: [number(4), number(5), number(6)],
            }
        })
        .collect()
}

fn distance(a: [f64; 3], b: [f64; 3]) -> f64 {
    ((a[0] - b[0]).powi(2) + (a[1] - b[1]).powi(2) + (a[2] - b[2]).powi(2)).sqrt()
}

#[test]
fn every_shifted_crs_matches_the_proj_reference() {
    let rows = reference_rows();
    assert!(
        rows.len() > 1000,
        "fixture is incomplete: {} rows",
        rows.len()
    );
    let mut failures = Vec::new();
    let mut worst = 0.0_f64;
    for row in &rows {
        let got = Reprojector::new(SourceCrs::new(row.epsg)).and_then(|rp| rp.to_ecef(row.src));
        match got {
            Ok(ecef) => {
                let delta = distance(ecef, row.expected_ecef);
                worst = worst.max(delta);
                if delta.is_nan() || delta > PARITY_TOLERANCE_M {
                    failures.push(format!(
                        "EPSG:{} {:?}: {delta:.6} m from PROJ",
                        row.epsg, row.src
                    ));
                }
            }
            Err(e) => failures.push(format!("EPSG:{} {:?}: {e}", row.epsg, row.src)),
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} reference rows differ from PROJ by more than {PARITY_TOLERANCE_M} m \
         (worst {worst:.6} m); first rows:\n{}",
        failures.len(),
        rows.len(),
        failures
            .iter()
            .take(20)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
}
